index c91d5da42..4eaecee1b 100644
--- a/drivers/misc/fastrpc.c
+++ b/drivers/misc/fastrpc.c
@@ -250,6 +250,8 @@ struct fastrpc_invoke_ctx {
 	uintptr_t *buf_pv;
 	struct fastrpc_buf_overlap *olaps;
