 	u32 *entry_ptr;
-	int count = 0;
+	int copied = 0, count = 0;
 
 	if (copy_from_user(&entries, arg, sizeof(entries)))
 		return -EFAULT;
@@ -1637,12 +1637,13 @@ static int cm_mport_get_list(void __user *arg)
 			*entry_ptr = (cm->mport->id << 16) |
