+	unsigned long start_addr;
 	bool needs_fallback = false;
 
-fallback:
-	addr = vmf->address;
-
 	/* Did we COW the page? */
 	if (is_cow)
 		page = vmf->cow_page;
@@ -5695,7 +5693,7 @@ vm_fault_t finish_fault(struct vm_fault *vmf)
 			return ret;
 	}
 
